class EmbedVectorField(Node):
    def __init__(self, parent_node_id : str):
        super().__init__(parent_node_id, Vector, SurfaceOrVolumeEmbedding, locals())

    @classmethod
    def chat_description(cls):
        return "queued embedding vector field"

    @classmethod
    def description(cls):
        return 'Creates a geometric embedding of a node of type vector.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type vector that should be embedded'}

    @classmethod
    def guardrails(cls):
        return [_visualize_alongside_descriptors_guardrail]

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, SquareOrCubeEmbedding):
            return False, f"Cannot embed a node of type {self.node_type.get_mcp_name()} along with another "\
                          f"of type {other.node_type.get_mcp_name()}. They will overlap in the visualization"

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):
        array = paraview_vti_to_numpy(parent_data.data)
        lic_array = lic(array, 4)
        data = numpy_to_paraview_vti(lic_array, 4)

        return SurfaceOrVolumeEmbedding(data, "grey", None, array.shape)

